shader_2d:
fn variation_plugin_example(p: vec2<f32>, xform_id: u32, variation_id: u32) -> vec2<f32> {
    let scale = get_param(xform_id, variation_id, 0u);
    let twist = get_param(xform_id, variation_id, 1u);
    let r = length(p);
    let a = atan2(p.y, p.x) + twist * r;
    return vec2<f32>(cos(a), sin(a)) * r * scale;
}

shader_3d:
fn variation_plugin_example(p: vec3<f32>, xform_id: u32, variation_id: u32) -> vec3<f32> {
    let scale = get_param(xform_id, variation_id, 0u);
    let twist = get_param(xform_id, variation_id, 1u);
    let r = length(p.xy);
    let a = atan2(p.y, p.x) + twist * r;
    return vec3<f32>(cos(a) * r * scale, sin(a) * r * scale, p.z * scale);
}
